head.script:
scwin.onpageload = function() {
	scwin.vScrenID = "ULDMGT50306";

    rdo_submitFaq.setValue("0");

    scwin.select_list_call();
};

/********************************************** 
 * 함수명   : scwin.select_list_call()
 * 설명     : 초기 조회 
 ***********************************************/
scwin.select_list_call = function() {

    dma_select_list.set("mode",  rdo_submitFaq.getValue());

    $c.sbm.execute(sbm_select_list, dma_select_list.getJSON());
}
scwin.sbm_select_list_submitdone = function (e) {
    const result = e.responseJSON;

    if(result.success) {
        const obj = result.body;
        console.log("len : "+ obj.length);
        dlt_select_list_content.setJSON(obj); 
    }
    else{
        $c.win.alert(result.message);
    }
};

scwin.rdo_submitFaq_onchange = function (info) {
	 scwin.select_list_call();
};



scwin.grd_submitFAQ_oncellclick = async function (rowIndex, columnIndex, columnId) {
  console.log ("columnIndex :" + columnIndex + " rowIndex:"+ rowIndex+ "  columnId:"+ columnId);
    if(columnIndex == 2)
    {
        dma_param.setJSON(dlt_select_list_content.getRowJSON(rowIndex));
        console.log("2dma_param :"+ JSON.stringify(dma_param.getJSON()));

        const data = { type: "confirm", jval: dma_param.getJSON(),  callBackParam:"scwin.grd_popListUpdateCallback", mode:"update"}; 
        const options = {
            id: "ConfirmPop",
            title: "Confirm_Pop",
            width:"920px",
            height: "470px"
        };


        const result = await $c.win.openPopup("/ui/mgt/ULDMGT50315.xml", options, data);
        scwin.grd_popListUpdateCallback(result);
    }

    if(columnIndex == 5)
    {

        dma_param.setJSON(dlt_select_list_content.getRowJSON(rowIndex));
        console.log("5dma_param :"+ JSON.stringify(dma_param.getJSON()));
        const data = { type: "confirm", jval: dma_param.getJSON(),  callBackParam:"scwin.grd_menuUpdateCallback" }; 
        const options = {
            id: "ConfirmPop",
            title: "Confirm_Pop",
            width:"920px",
            height: "470px"
        };

        const result = await $c.win.openPopup("/ui/mgt/ULDMGT50323.xml", options, data);
        scwin.grd_menuUpdateCallback(result);

    };
    if(columnIndex == 6)
    {
        var rmenuId = dlt_select_list_content.getCellData(rowIndex, "helpClssId");
        var rmenuNm = dlt_select_list_content.getCellData(rowIndex, "helpClssNm");
        var vmsg = "메뉴 "+ rmenuNm +"(" + rmenuId + ") 을(를) 삭제하시겠습니까?";


        if (await $c.win.confirm(vmsg)) 
        { 
            dma_delete.set("menuId", rmenuId);
            scwin.res = await $c.sbm.execute(sbm_delete,  dma_delete.getJSON());
            if (scwin.res.responseJSON.success == true) {
                scwin.res.saveFlag = "delete";
                $c.win.closePopup(scwin.res);

                scwin.select_list_call();
            }            
        } else {
            $c.win.closePopup();
        }

    };
}

scwin.sbm_delete_submitdone = function (e) {
    const result = e.responseJSON;

    if(result.success) {
       scwin.select_list_call();
    }
    else{
        $c.win.alert(result.message);
    }
};


scwin.btn_FaqInsert_onclick = async function (e) {
	//console.log("faqInsert");

    const data = { type: "confirm", jval: dlt_select_list_content.getRowJSON(0)}; 
    const options = {
        id: "ConfirmPop",
        title: "Confirm_Pop",
        width:"920px",
        height: "470px"
    };

    // $c.win.openPopup("/ui/mgt/ULDMGT50307.xml", options, data);
    const result = await $c.win.openPopup("/ui/mgt/ULDMGT50307.xml", options, data);
    scwin.grd_afterFaqInsertCallback(result);
};

scwin.btnDistributaryInsert_onclick = async function (e) {
	console.log("DistributaryInsert");

    dma_param.set("mode", "create");
    //dma_param.set("helpClssId", "0300000114");
    //dma_param.set("helpTpCd", "03");

    const data = { type: "confirm", jval: dma_param.getJSON(),  callBackFn:"scwin.grd_afterBtnDistributeInsertCallback"}; 
    const options = {
        id: "ConfirmPop",
        title: "Confirm_Pop",
        width:"920px",
        height: "470px"
    };

    //$c.win.openPopup("/ui/mgt/ULDMGT50313.xml", options, data);

    const result = await $c.win.openPopup("/ui/mgt/ULDMGT50313.xml", options, data);
    scwin.grd_afterBtnDistributeInsertCallback(result);
};

scwin.grd_popListUpdateCallback = function()
{
    console.log("grd_popListUpdateCallback");
}
scwin.grd_afterFaqInsertCallback = function()
{

    console.log("grd_afterFaqInsertCallback");
}

scwin.grd_afterBtnDistributeInsertCallback=function()
{
    console.log("grd_afterBtnDistributeInsertCallback");
    scwin.select_list_call();


}
